// Bootstrap only: use the installed Convex SDK templates without a deployment.
// Once connected, `npx convex dev` owns these generated files.
import { mkdir, readdir, readFile, writeFile } from "node:fs/promises";
import { format } from "prettier";
import { apiCodegen } from "../node_modules/convex/dist/esm/cli/codegen_templates/api.js";
import { serverCodegen } from "../node_modules/convex/dist/esm/cli/codegen_templates/server.js";
await mkdir("convex/_generated", { recursive: true });
const modules = (await readdir("convex")).filter(
  (f) =>
    f.endsWith(".ts") &&
    ![
      "schema.ts",
      "auth.config.ts",
      "crons.ts",
      "http.ts",
      "model.ts",
    ].includes(f),
);
const api = apiCodegen(modules, { useTypeScript: false });
const server = serverCodegen({ useTypeScript: false });
await writeFile("convex/_generated/api.js", api.JS);
await writeFile("convex/_generated/api.d.ts", api.DTS);
await writeFile("convex/_generated/server.js", server.JS);
await writeFile("convex/_generated/server.d.ts", server.DTS);
await writeFile(
  "convex/_generated/dataModel.d.ts",
  `// Offline schema-derived types; regenerated by npx convex dev.
import type { DataModelFromSchemaDefinition, DocumentByName, TableNamesInDataModel, SystemTableNames } from "convex/server";
import type { GenericId } from "convex/values";
import schema from "../schema.js";
export type DataModel = DataModelFromSchemaDefinition<typeof schema>;
export type TableNames = TableNamesInDataModel<DataModel>;
export type Doc<TableName extends TableNames> = DocumentByName<DataModel, TableName>;
export type Id<TableName extends TableNames | SystemTableNames> = GenericId<TableName>;
`,
);
for (const name of await readdir("convex/_generated")) {
  const path = `convex/_generated/${name}`;
  await writeFile(
    path,
    await format(await readFile(path, "utf8"), { filepath: path }),
  );
}
console.log(
  "Convex SDK templates generated offline. No deployment was contacted.",
);
